bash_cmds:
C=/tmp/claude-0/cand; 
node-assets optimize assets/toycar.glb -o $C/q80.glb --texture-quality 80 >/dev/null 2>&1;
node-assets optimize assets/toycar.glb -o $C/q75dq90.glb --texture-quality 75 --texture-data-quality 90 >/dev/null 2>&1;
node-assets optimize assets/toycar.glb -o $C/meshopt.glb --geometry meshopt >/dev/null 2>&1;
node-assets optimize assets/toycar.glb -o $C/draco.glb --geometry draco >/dev/null 2>&1;
for f in q80 q75dq90 meshopt draco; do echo "== $f"; node-assets inspect $C/$f.glb --against assets/toycar.glb --view 1024 --network 4g 2>&1 | grep -E "^(bytes|textures|decoders|required_extensions|fidelity|load_s|load_detail):"; done
